insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('d5d77de7-f784-53aa-a54c-615191edb0df','Moneda Aberrante','habilidades_generales','habilidad','aprobado','Una moneda disparada mediante Inercia perfora, rebota entre enemigos y cambia de trayectoria. Kion imbuye una moneda con aceleraciones y vectores precisos. Descubrió el principio al escupir una moneda desde la boca cuando estaba inmovilizado: atravesó la cabeza del jefe mercenario y rebotó contra los demás. Disparos casi instantáneos, ricochets entre varios objetivos, cambios de dirección, retorno del proyectil y conducción de otras leyes. Las monedas funcionan como proyectiles pequeños y prescindibles; no son armas que necesiten resistir las aceleraciones reiteradas de su estilo. Daño, rebotes y alcance pendientes de definir.','[{"id": "moneda-errante", "nombre": "Moneda Aberrante", "descripcion": "Una moneda disparada mediante Inercia perfora, rebota entre enemigos y cambia de trayectoria. Kion imbuye una moneda con aceleraciones y vectores precisos. Descubrió el principio al escupir una moneda desde la boca cuando estaba inmovilizado: atravesó la cabeza del jefe mercenario y rebotó contra los demás. Disparos casi instantáneos, ricochets entre varios objetivos, cambios de dirección, retorno del proyectil y conducción de otras leyes. Las monedas funcionan como proyectiles pequeños y prescindibles; no son armas que necesiten resistir las aceleraciones reiteradas de su estilo. Daño, rebotes y alcance pendientes de definir.", "efecto": "dano", "estado": "Moneda Aberrante", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-treasure-glint", "escala": 1.5, "recorrido": "foundry-treasure-glint"}, "recurso": {"nombre": "Saco de monedas", "inicial": 12, "cambio": -1}, "companero_magico": "Navy"}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('dd3fec46-61d1-5afc-a85e-95557f56ccfb','Paso Inercial','habilidades_generales','habilidad','aprobado','Esquiva y se reposiciona tan rápido que parece teletransportarse. Impone aceleraciones, cambios de dirección y frenadas bruscas a su propio cuerpo. Antes eran sacudidas torpes; con los años, el movimiento se volvió fluido y casi invisible para el observador. Esquivar golpes y desplazarse entre ataques o enemigos sin necesidad de teletransportarse. No es teletransporte real. Limitless sellada evita que sus propias aceleraciones lo lesionen, pero no garantiza esquivar un ataque que no percibe.','[{"id": "paso-inercial", "nombre": "Paso Inercial", "descripcion": "Esquiva y se reposiciona tan rápido que parece teletransportarse. Impone aceleraciones, cambios de dirección y frenadas bruscas a su propio cuerpo. Antes eran sacudidas torpes; con los años, el movimiento se volvió fluido y casi invisible para el observador. Esquivar golpes y desplazarse entre ataques o enemigos sin necesidad de teletransportarse. No es teletransporte real. Limitless sellada evita que sus propias aceleraciones lo lesionen, pero no garantiza esquivar un ataque que no percibe.", "efecto": "estado", "estado": "Paso Inercial", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 1.5}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('f12b0b17-eab0-5303-a6a2-ece1b6a1d498','Golpe de Transferencia','habilidades_generales','habilidad','aprobado','Convierte un golpe corto en un impacto letal mediante la aceleración del puño. La propia Inercia potencia la velocidad y la transferencia de impulso durante el contacto, sin requerir musculatura sobrehumana. Kion puede golpear con sus puños desnudos. Puñetazos extremadamente veloces y potentes incluso con muy poco recorrido. La velocidad del golpe no implica invulnerabilidad frente a ataques enemigos.','[{"id": "golpe-transferencia", "nombre": "Golpe de Transferencia", "descripcion": "Convierte un golpe corto en un impacto letal mediante la aceleración del puño. La propia Inercia potencia la velocidad y la transferencia de impulso durante el contacto, sin requerir musculatura sobrehumana. Kion puede golpear con sus puños desnudos. Puñetazos extremadamente veloces y potentes incluso con muy poco recorrido. La velocidad del golpe no implica invulnerabilidad frente a ataques enemigos.", "efecto": "dano", "estado": "Golpe de Transferencia", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 1.5}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('9c36e696-3df8-580b-b6e5-304f13fed9a7','Ancla Inercial','habilidades_generales','habilidad','aprobado','Detiene de golpe el impulso de un impacto entrante. Al interceptar un puño, arma u objeto en movimiento, Kion altera su inercia para frenarlo o anclarlo. Paradas a mano limpia, bloquear golpes y frustrar embestidas. Frenar el movimiento no vuelve indestructible la materia que lo recibe.','[{"id": "ancla-inercial", "nombre": "Ancla Inercial", "descripcion": "Detiene de golpe el impulso de un impacto entrante. Al interceptar un puño, arma u objeto en movimiento, Kion altera su inercia para frenarlo o anclarlo. Paradas a mano limpia, bloquear golpes y frustrar embestidas. Frenar el movimiento no vuelve indestructible la materia que lo recibe.", "efecto": "estado", "estado": "Ancla Inercial", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 1.5}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('410991a7-1124-5aee-9fe3-e863519f3be7','Caída Prestada','habilidades_generales','habilidad','aprobado','Acelera o amortigua caídas sin alterar todavía la gravedad universal. Cambia la velocidad de descenso de sí mismo o de objetos afectados. Aterrizar sin daño propio, acelerar proyectiles que caen. No equivale al control gravitatorio de Limitless despierta.','[{"id": "caida-prestada", "nombre": "Caída Prestada", "descripcion": "Acelera o amortigua caídas sin alterar todavía la gravedad universal. Cambia la velocidad de descenso de sí mismo o de objetos afectados. Aterrizar sin daño propio, acelerar proyectiles que caen. No equivale al control gravitatorio de Limitless despierta.", "efecto": "estado", "estado": "Caída Prestada", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 1.5}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('05c9623f-52c9-5a63-a00a-98fabe7fbb73','Puño Inercial','habilidades_generales','habilidad','aprobado','Un puñetazo desnudo adquiere una aceleración explosiva en el instante del contacto. Kion se sirve de su propio cuerpo como conductor de Inercia. La velocidad del puño aumenta de manera súbita y el golpe transmite una fuerza que no coincide con su postura aparentemente relajada. Ataque directo a puños; base de su estilo marcial moderno. Técnica distinta del control del impacto posterior. El daño y su coste de PH quedan por definir.','[{"id": "punos-inerciales", "nombre": "Puño Inercial", "descripcion": "Un puñetazo desnudo adquiere una aceleración explosiva en el instante del contacto. Kion se sirve de su propio cuerpo como conductor de Inercia. La velocidad del puño aumenta de manera súbita y el golpe transmite una fuerza que no coincide con su postura aparentemente relajada. Ataque directo a puños; base de su estilo marcial moderno. Técnica distinta del control del impacto posterior. El daño y su coste de PH quedan por definir.", "efecto": "dano", "estado": "Puño Inercial", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 1.5}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('333059a6-63e7-56a1-ae61-6c4724677939','Segundo Impacto','habilidades_generales','habilidad','aprobado','Tras conectar el puño, proyecta un vector recto que golpea por segunda vez. Primer impacto: contacto físico. Segundo impacto: un vector rectilíneo sale inmediatamente del puño y transmite otro golpe en la misma dirección. No necesita volver a mover el brazo. Castigar objetivos resistentes o engañar a quienes creen haber bloqueado ya el ataque. La longitud, el daño y la posibilidad de bloquear el segundo vector siguen pendientes de reglas.','[{"id": "segundo-impacto", "nombre": "Segundo Impacto", "descripcion": "Tras conectar el puño, proyecta un vector recto que golpea por segunda vez. Primer impacto: contacto físico. Segundo impacto: un vector rectilíneo sale inmediatamente del puño y transmite otro golpe en la misma dirección. No necesita volver a mover el brazo. Castigar objetivos resistentes o engañar a quienes creen haber bloqueado ya el ataque. La longitud, el daño y la posibilidad de bloquear el segundo vector siguen pendientes de reglas.", "efecto": "dano", "estado": "Segundo Impacto", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 1.5}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('26f44ff1-88b0-5df1-92cd-505f11b85ee6','Vuelo Inercial','habilidades_generales','habilidad','aprobado','Simula el vuelo controlando aceleraciones y frenadas de su propio cuerpo. Kion aplica vectores sucesivos que sostienen y desplazan su cuerpo en el aire. Es movimiento gobernado por Inercia; no equivale todavía al dominio absoluto de la gravedad que tendrá con Limitless despierta. Viajar, elevarse, flotar y cambiar de rumbo. Es la única aplicación extraordinaria que usa regularmente fuera del combate. Velocidad, altura máxima, duración y PH quedan pendientes.','[{"id": "vuelo-inercial", "nombre": "Vuelo Inercial", "descripcion": "Simula el vuelo controlando aceleraciones y frenadas de su propio cuerpo. Kion aplica vectores sucesivos que sostienen y desplazan su cuerpo en el aire. Es movimiento gobernado por Inercia; no equivale todavía al dominio absoluto de la gravedad que tendrá con Limitless despierta. Viajar, elevarse, flotar y cambiar de rumbo. Es la única aplicación extraordinaria que usa regularmente fuera del combate. Velocidad, altura máxima, duración y PH quedan pendientes.", "efecto": "estado", "estado": "Vuelo Inercial", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 1.5}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('e541ba15-6361-5f12-8c95-615096256bfc','Supervelocidad Simulada','habilidades_generales','habilidad','aprobado','Puede aumentar su velocidad de desplazamiento hasta aparentar supervelocidad. Acelera su cuerpo usando Inercia y gestiona las frenadas para conservar el control. Limitless sellada evita el daño de su propia aceleración. Carreras, persecuciones y desplazamientos veloces; el mismo principio se aplica a sus esquivas. Fuera del combate prácticamente no la emplea por costumbre, aunque puede hacerlo.','[{"id": "supervelocidad-inercial", "nombre": "Supervelocidad Simulada", "descripcion": "Puede aumentar su velocidad de desplazamiento hasta aparentar supervelocidad. Acelera su cuerpo usando Inercia y gestiona las frenadas para conservar el control. Limitless sellada evita el daño de su propia aceleración. Carreras, persecuciones y desplazamientos veloces; el mismo principio se aplica a sus esquivas. Fuera del combate prácticamente no la emplea por costumbre, aunque puede hacerlo.", "efecto": "estado", "estado": "Supervelocidad Simulada", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 1.5}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('a852e5a1-cfe3-516e-a653-d550888cf789','Superfuerza Simulada','habilidades_generales','habilidad','aprobado','Imita la superfuerza al transferir enormes impulsos con sus movimientos. No desarrolla músculos sobrehumanos: utiliza Inercia para amplificar el efecto mecánico de un movimiento de su cuerpo. Propulsar objetos, golpes, empujes y acciones físicas que de otro modo excederían su fuerza natural. Fuera del combate no suele utilizarla. No implica levantar objetos mágicamente sin aplicar movimiento.','[{"id": "superfuerza-inercial", "nombre": "Superfuerza Simulada", "descripcion": "Imita la superfuerza al transferir enormes impulsos con sus movimientos. No desarrolla músculos sobrehumanos: utiliza Inercia para amplificar el efecto mecánico de un movimiento de su cuerpo. Propulsar objetos, golpes, empujes y acciones físicas que de otro modo excederían su fuerza natural. Fuera del combate no suele utilizarla. No implica levantar objetos mágicamente sin aplicar movimiento.", "efecto": "estado", "estado": "Superfuerza Simulada", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 1.5}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('3f5a22b7-7f27-5dfe-bbfb-e3e6c6126dab','Recíproco','habilidades_generales','habilidad','aprobado','Redirige la reacción de un impacto físico hacia el atacante o, tras su descubrimiento, hacia el terreno. Cuando un golpe establece contacto con Kion, manipula la fuerza reactiva a través de una conexión física real. Al principio solo aprendió a devolverla hacia quien lo golpea; después descubre que, apoyando los pies, puede descargarla al suelo. Reacción ante un ataque cuerpo a cuerpo: devolver la fuerza al atacante. Con apoyo firme: conducir un proyectil físico interceptado hacia el suelo; puede fracturar el terreno. Propuesta de prueba: 3 PH y una reacción por ronda. Necesita un medio físico y una salida para la reacción. Si está en el aire y recibe un ataque a distancia, recibe el daño completo. No devuelve una bola de fuego explosiva a su lanzador sin conexión; redirigir la reacción no garantiza neutralizar toda fuente de daño.','[{"id": "reciproco", "nombre": "Recíproco", "descripcion": "Redirige la reacción de un impacto físico hacia el atacante o, tras su descubrimiento, hacia el terreno. Cuando un golpe establece contacto con Kion, manipula la fuerza reactiva a través de una conexión física real. Al principio solo aprendió a devolverla hacia quien lo golpea; después descubre que, apoyando los pies, puede descargarla al suelo. Reacción ante un ataque cuerpo a cuerpo: devolver la fuerza al atacante. Con apoyo firme: conducir un proyectil físico interceptado hacia el suelo; puede fracturar el terreno. Propuesta de prueba: 3 PH y una reacción por ronda. Necesita un medio físico y una salida para la reacción. Si está en el aire y recibe un ataque a distancia, recibe el daño completo. No devuelve una bola de fuego explosiva a su lanzador sin conexión; redirigir la reacción no garantiza neutralizar toda fuente de daño.", "efecto": "estado", "estado": "Recíproco", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Acción y Reacción", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-shockwave-ring", "escala": 1.5}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('469b58ed-d45b-52a7-94e1-e027bb9d79ad','Martillo y Yunque','habilidades_generales','habilidad','aprobado','Un puñetazo se convierte en una compresión entre el golpe de Kion y una fuerza que asciende desde el apoyo del enemigo. Kion golpea a un enemigo que mantiene contacto con una superficie sólida. La reacción del impacto se transmite al terreno y regresa desde su punto de apoyo, comprimiendo el objetivo entre fuerzas opuestas. Gran daño a un solo objetivo apoyado en el suelo. Propuesta de prueba: un golpe más 1d6 adicional por compresión, coste de 4 PH; el modelo anterior consideraba 2d6 + 1d6. Si el enemigo está suspendido o no hay continuidad con el terreno, no aplica el efecto de compresión. Daños y PH son cifras de prueba, no canon cerrado.','[{"id": "martillo-yunque", "nombre": "Martillo y Yunque", "descripcion": "Un puñetazo se convierte en una compresión entre el golpe de Kion y una fuerza que asciende desde el apoyo del enemigo. Kion golpea a un enemigo que mantiene contacto con una superficie sólida. La reacción del impacto se transmite al terreno y regresa desde su punto de apoyo, comprimiendo el objetivo entre fuerzas opuestas. Gran daño a un solo objetivo apoyado en el suelo. Propuesta de prueba: un golpe más 1d6 adicional por compresión, coste de 4 PH; el modelo anterior consideraba 2d6 + 1d6. Si el enemigo está suspendido o no hay continuidad con el terreno, no aplica el efecto de compresión. Daños y PH son cifras de prueba, no canon cerrado.", "efecto": "dano", "estado": "Martillo y Yunque", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Acción y Reacción", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-shockwave-ring", "escala": 1.5}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('c26a61c9-2e76-5272-9df5-06f70be2128e','Moneda de Peaje','habilidades_generales','habilidad','aprobado','Convierte el contacto de una moneda con un arma o armadura en una reacción dañina transmitida al portador. Kion dispara una moneda y manipula la reacción en el impacto: una espada transmite la sacudida a la muñeca que la empuña; un escudo conduce la fuerza al brazo que lo sostiene. Puede usar Inercia como propulsión, pero el efecto distintivo procede de Acción y Reacción. Ofensiva a distancia mediante una moneda. Propuesta de prueba: 2d6 contundente y salvación de Resistencia para desarmar o inutilizar momentáneamente la pieza; 3 PH. Requiere que el proyectil impacte un conductor físico vinculado al portador. No actúa mágicamente sobre rivales desconectados; daño, CD y PH son provisionales.','[{"id": "moneda-peaje", "nombre": "Moneda de Peaje", "descripcion": "Convierte el contacto de una moneda con un arma o armadura en una reacción dañina transmitida al portador. Kion dispara una moneda y manipula la reacción en el impacto: una espada transmite la sacudida a la muñeca que la empuña; un escudo conduce la fuerza al brazo que lo sostiene. Puede usar Inercia como propulsión, pero el efecto distintivo procede de Acción y Reacción. Ofensiva a distancia mediante una moneda. Propuesta de prueba: 2d6 contundente y salvación de Resistencia para desarmar o inutilizar momentáneamente la pieza; 3 PH. Requiere que el proyectil impacte un conductor físico vinculado al portador. No actúa mágicamente sobre rivales desconectados; daño, CD y PH son provisionales.", "efecto": "dano", "estado": "Moneda de Peaje", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Acción y Reacción", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-treasure-glint", "escala": 1.5, "recorrido": "foundry-treasure-glint"}, "recurso": {"nombre": "Saco de monedas", "inicial": 12, "cambio": -1}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('4725cd1a-9a9e-58fc-bf79-04e0f263cb72','Sentencia del Suelo','habilidades_generales','habilidad','aprobado','Kion golpea una superficie y dirige la reacción a través del terreno hasta los enemigos apoyados en él. Un puñetazo o pisotón produce una fuerza real que se transmite por un suelo continuo. Kion reorganiza su reacción para provocar impactos desde abajo alrededor del punto de contacto. Daño de área y derribo. Propuesta de prueba: 2d6 contundente, radio de 3 casillas, salvación de Resistencia para evitar caída, coste 5 PH. No afecta a objetivos voladores ni a través de superficies desconectadas. Radio, daño, CD y PH son provisionales.','[{"id": "sentencia-suelo", "nombre": "Sentencia del Suelo", "descripcion": "Kion golpea una superficie y dirige la reacción a través del terreno hasta los enemigos apoyados en él. Un puñetazo o pisotón produce una fuerza real que se transmite por un suelo continuo. Kion reorganiza su reacción para provocar impactos desde abajo alrededor del punto de contacto. Daño de área y derribo. Propuesta de prueba: 2d6 contundente, radio de 3 casillas, salvación de Resistencia para evitar caída, coste 5 PH. No afecta a objetivos voladores ni a través de superficies desconectadas. Radio, daño, CD y PH son provisionales.", "efecto": "dano", "estado": "Sentencia del Suelo", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Acción y Reacción", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-shockwave-ring", "escala": 1.5}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('8bd3617d-3482-5de5-844f-bbae30682a10','Absorción','habilidades_generales','habilidad','aprobado','Intercepciona energía, la procesa y la almacena. Capta la energía accesible de magia enemiga y fenómenos energéticos; absorción, proceso y reserva son una sola técnica. Mitigar una bola de fuego, recuperar energía de ataques para otras técnicas. No anula por defecto maldiciones o efectos conceptuales; capacidad máxima pendiente.','[{"id": "absorcion", "nombre": "Absorción", "descripcion": "Intercepciona energía, la procesa y la almacena. Capta la energía accesible de magia enemiga y fenómenos energéticos; absorción, proceso y reserva son una sola técnica. Mitigar una bola de fuego, recuperar energía de ataques para otras técnicas. No anula por defecto maldiciones o efectos conceptuales; capacidad máxima pendiente.", "efecto": "estado", "estado": "Absorción", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Conservación", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-magic-circle", "escala": 1.5}, "recurso": {"nombre": "Energía absorbida", "inicial": 0, "cambio": 1}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('8973619e-bca8-55d3-81ee-baa853dde805','Reconstrucción','habilidades_generales','habilidad','aprobado','Consume energía para regenerar tejidos, huesos y órganos propios. Acelera procesos de reparación biológica con energía y magia. Recuperar HP cuando el GM defina la escala de regeneración. No revierte automáticamente una muerte definitiva.','[{"id": "reconstruccion", "nombre": "Reconstrucción", "descripcion": "Consume energía para regenerar tejidos, huesos y órganos propios. Acelera procesos de reparación biológica con energía y magia. Recuperar HP cuando el GM defina la escala de regeneración. No revierte automáticamente una muerte definitiva.", "efecto": "curacion", "estado": "Reconstrucción", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Conservación", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-holy-heal", "escala": 1.5}, "recurso": {"nombre": "Energía absorbida", "inicial": 0, "cambio": -1}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('f512318d-327a-57e5-a532-951dc1efde53','Punto Cero','habilidades_generales','habilidad','aprobado','Extrae calor de una región hasta aproximarse mágicamente al cero absoluto. Retira energía térmica y puede dirigirla hacia su reserva. Congelar materiales, detener procesos térmicos y cargar Liberación. Cero absoluto exacto es sobrenatural en YUGEN.','[{"id": "punto-cero", "nombre": "Punto Cero", "descripcion": "Extrae calor de una región hasta aproximarse mágicamente al cero absoluto. Retira energía térmica y puede dirigirla hacia su reserva. Congelar materiales, detener procesos térmicos y cargar Liberación. Cero absoluto exacto es sobrenatural en YUGEN.", "efecto": "estado", "estado": "Punto Cero", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Conservación", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-magic-circle", "escala": 1.5}, "recurso": {"nombre": "Energía absorbida", "inicial": 0, "cambio": 1}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('c657713f-b017-599a-bc3e-44b869fa25b0','Liberación','habilidades_generales','habilidad','aprobado','Expulsa toda la energía acumulada como onda cinética desde su cuerpo, en todas direcciones. Transforma la reserva almacenada en una expansión cinética omnidireccional. Despejar enemigos cercanos, contraatacar tras Absorción o Punto Cero. Vacía la reserva; Kion está protegido de su propia liberación.','[{"id": "liberacion", "nombre": "Liberación", "descripcion": "Expulsa toda la energía acumulada como onda cinética desde su cuerpo, en todas direcciones. Transforma la reserva almacenada en una expansión cinética omnidireccional. Despejar enemigos cercanos, contraatacar tras Absorción o Punto Cero. Vacía la reserva; Kion está protegido de su propia liberación.", "efecto": "dano", "estado": "Liberación", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Conservación", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-magic-circle", "escala": 1.5}, "recurso": {"nombre": "Energía absorbida", "inicial": 0, "cambio": -1}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('48b372fd-6811-5d31-b650-c5ac3e1f448e','Dispersión','habilidades_generales','habilidad','aprobado','Una explosión de vectores que arroja todo desde el centro. Expande movimientos radiales desde una esfera plateada de núcleo oscuro. Golpear y expulsar grupos con impacto físico devastador. PH alto; destrucción considerable.','[{"id": "dispersion", "nombre": "Dispersión", "descripcion": "Una explosión de vectores que arroja todo desde el centro. Expande movimientos radiales desde una esfera plateada de núcleo oscuro. Golpear y expulsar grupos con impacto físico devastador. PH alto; destrucción considerable.", "efecto": "estado", "estado": "Dispersión", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('e3fc7aa5-129d-5a28-abf5-447f5ade1824','Vector Absoluto','habilidades_generales','habilidad','aprobado','Todos los vectores del volumen se alinean en una dirección destructiva. Concentra la dirección del movimiento para perforar en línea. Ataque frontal de gran penetración. Es concentración de vectores, no un rayo de calor.','[{"id": "vector-absoluto", "nombre": "Vector Absoluto", "descripcion": "Todos los vectores del volumen se alinean en una dirección destructiva. Concentra la dirección del movimiento para perforar en línea. Ataque frontal de gran penetración. Es concentración de vectores, no un rayo de calor.", "efecto": "estado", "estado": "Vector Absoluto", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('4fc3e1ff-e0dd-572c-8bcc-f59df1f56633','Quietud Absoluta','habilidades_generales','habilidad','aprobado','Implosión: atrae materia violentamente y detiene su movimiento de golpe. Impone vectores hacia el centro y los cancela en un punto. Arrasar estructuras por colapso interno. Sellado: todavía NO es un agujero negro real.','[{"id": "quietud-absoluta", "nombre": "Quietud Absoluta", "descripcion": "Implosión: atrae materia violentamente y detiene su movimiento de golpe. Impone vectores hacia el centro y los cancela en un punto. Arrasar estructuras por colapso interno. Sellado: todavía NO es un agujero negro real.", "efecto": "estado", "estado": "Quietud Absoluta", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('3d5b0e5a-9ffb-5c53-b4a8-fa663a535e11','Talión','habilidades_generales','habilidad','aprobado','Comprime al objetivo entre la fuerza de un primer impacto y su reacción dirigida desde el lado contrario. La esfera se abre en dos polos enfrentados. Uno genera una presión violenta sobre la superficie del objetivo; el otro recibe y reorienta la reacción para atacar físicamente desde el extremo opuesto. Ataque de compresión masiva contra un objetivo resistente, sin que Kion tenga que recibir personalmente un golpe. Un Axioma sellado exige mucho PH y su impacto debe alcanzar al objetivo. La destrucción procede de fuerzas opuestas, no de crear energía infinita.','[{"id": "axioma-talion", "nombre": "Talión", "descripcion": "Comprime al objetivo entre la fuerza de un primer impacto y su reacción dirigida desde el lado contrario. La esfera se abre en dos polos enfrentados. Uno genera una presión violenta sobre la superficie del objetivo; el otro recibe y reorienta la reacción para atacar físicamente desde el extremo opuesto. Ataque de compresión masiva contra un objetivo resistente, sin que Kion tenga que recibir personalmente un golpe. Un Axioma sellado exige mucho PH y su impacto debe alcanzar al objetivo. La destrucción procede de fuerzas opuestas, no de crear energía infinita.", "efecto": "dano", "estado": "Talión", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Acción y Reacción", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-shockwave-ring", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('93a8eca0-cac8-5b84-b9d0-b9b08f774e6a','Juicio de la Tierra','habilidades_generales','habilidad','aprobado','Un impacto colosal sobre el suelo desencadena reacciones que fracturan y levantan una extensa región. Kion deposita un Axioma sobre el terreno: al activarse, genera un golpe real y redirige las reacciones en distintas direcciones del suelo conectado. Regiones enteras empujan a otras. Terremoto destructivo, roturas y columnas de roca que golpean a los objetivos apoyados. Requiere un medio continuo que transmita la fuerza. Su amplitud y PH son altos y quedan para el GM.','[{"id": "axioma-juicio-tierra", "nombre": "Juicio de la Tierra", "descripcion": "Un impacto colosal sobre el suelo desencadena reacciones que fracturan y levantan una extensa región. Kion deposita un Axioma sobre el terreno: al activarse, genera un golpe real y redirige las reacciones en distintas direcciones del suelo conectado. Regiones enteras empujan a otras. Terremoto destructivo, roturas y columnas de roca que golpean a los objetivos apoyados. Requiere un medio continuo que transmita la fuerza. Su amplitud y PH son altos y quedan para el GM.", "efecto": "estado", "estado": "Juicio de la Tierra", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Acción y Reacción", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-shockwave-ring", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('62e45737-cbf4-5d1f-a537-876f3888368e','Repercusión','habilidades_generales','habilidad','aprobado','Un Axioma se fragmenta en cuerpos de choque que encadenan colisiones reales entre objetivos separados. La esfera impacta, se descompone en fragmentos físicos de Axioma y usa la reacción de cada nueva colisión para orientar choques posteriores. Los enemigos no necesitan estar unidos: el fragmento es el medio que toca a cada uno. Barrido destructivo de múltiples objetivos o estructuras mediante trayectorias caóticas de impacto. Cada choque conserva sus límites de energía; no multiplica gratis la potencia. Sin Limitless despierta la formulación requiere mucho PH.','[{"id": "axioma-repercusion", "nombre": "Repercusión", "descripcion": "Un Axioma se fragmenta en cuerpos de choque que encadenan colisiones reales entre objetivos separados. La esfera impacta, se descompone en fragmentos físicos de Axioma y usa la reacción de cada nueva colisión para orientar choques posteriores. Los enemigos no necesitan estar unidos: el fragmento es el medio que toca a cada uno. Barrido destructivo de múltiples objetivos o estructuras mediante trayectorias caóticas de impacto. Cada choque conserva sus límites de energía; no multiplica gratis la potencia. Sin Limitless despierta la formulación requiere mucho PH.", "efecto": "dano", "estado": "Repercusión", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Acción y Reacción", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-shockwave-ring", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('f3b017a2-1ab8-558b-91f9-c643beee572c','Cero Absoluto','habilidades_generales','habilidad','aprobado','Congelación catastrófica en una zona extensa por extracción térmica. Extrae gran cantidad de energía térmica desde una esfera violeta proyectada. Devastar terreno y objetivos a distancia. Mayor escala que Punto Cero ordinario.','[{"id": "cero-absoluto", "nombre": "Cero Absoluto", "descripcion": "Congelación catastrófica en una zona extensa por extracción térmica. Extrae gran cantidad de energía térmica desde una esfera violeta proyectada. Devastar terreno y objetivos a distancia. Mayor escala que Punto Cero ordinario.", "efecto": "estado", "estado": "Cero Absoluto", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Conservación", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-magic-circle", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('57e23aca-ef04-54ce-8188-46f3e7b8512c','Supernova','habilidades_generales','habilidad','aprobado','Descarga a distancia enormes cantidades de energía en una explosión cinética. Concentra energía que la esfera deposita como presión y onda de choque. Destrucción radial con centro remoto. No asigna vectores a cada objetivo como Dispersión.','[{"id": "supernova", "nombre": "Supernova", "descripcion": "Descarga a distancia enormes cantidades de energía en una explosión cinética. Concentra energía que la esfera deposita como presión y onda de choque. Destrucción radial con centro remoto. No asigna vectores a cada objetivo como Dispersión.", "efecto": "dano", "estado": "Supernova", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Conservación", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-fire-nova", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('859736b2-f90a-5fe6-8630-32a799123c4c','Horizonte Muerto','habilidades_generales','habilidad','aprobado','Drena calor, movimiento y energía mágica de una región. Agota distintas fuentes energéticas accesibles, apagando sistemas progresivamente. Deshabilitar estructuras y hechizos mediante agotamiento energético. Su efecto principal es el drenaje, no una detonación automática.','[{"id": "horizonte-muerto", "nombre": "Horizonte Muerto", "descripcion": "Drena calor, movimiento y energía mágica de una región. Agota distintas fuentes energéticas accesibles, apagando sistemas progresivamente. Deshabilitar estructuras y hechizos mediante agotamiento energético. Su efecto principal es el drenaje, no una detonación automática.", "efecto": "estado", "estado": "Horizonte Muerto", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Conservación", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-magic-circle", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('bf447cea-a317-5669-b3ce-ba687108369f','Deuda del Movimiento','habilidades_generales','habilidad','aprobado','Arrebata movimiento de varias fuentes para concentrarlo en un único vector. La esfera absorbe energía cinética mientras Inercia gobierna la descarga dirigida. Parar proyectiles y convertir su impulso en una descarga devastadora. No multiplica energía; la captura inestable puede alterar el campo.','[{"id": "deuda-movimiento", "nombre": "Deuda del Movimiento", "descripcion": "Arrebata movimiento de varias fuentes para concentrarlo en un único vector. La esfera absorbe energía cinética mientras Inercia gobierna la descarga dirigida. Parar proyectiles y convertir su impulso en una descarga devastadora. No multiplica energía; la captura inestable puede alterar el campo.", "efecto": "estado", "estado": "Deuda del Movimiento", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Fusión", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('ba5bda7e-e1f7-5224-87ee-344007488bee','Comprensión Arcana','habilidades_generales','habilidad','aprobado','Aprende hechizos observados mediante una tirada de aprendizaje con +15. El bono +15 se suma al resultado de la tirada, NO es la CD. Al presenciar suficiente información de un hechizo, tira contra la CD que indique el GM. No es un don de Limitless.','[{"id": "comprension-arcana", "nombre": "Comprensión Arcana", "descripcion": "Aprende hechizos observados mediante una tirada de aprendizaje con +15. El bono +15 se suma al resultado de la tirada, NO es la CD. Al presenciar suficiente información de un hechizo, tira contra la CD que indique el GM. No es un don de Limitless.", "efecto": "estado", "estado": "Comprensión Arcana", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Propia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('763b4143-53a9-5f64-a1e9-a375e9b4ec04','Bola de Fuego','habilidades_generales','habilidad','aprobado','Hechizo ígneo que conoce de forma independiente a Limitless. Conjura una esfera de fuego como parte de su repertorio general. Puede detonarla cerca de sí mismo sin sufrir daño propio gracias a su protección innata. Ataque elemental habitual en el repertorio aprendido, aunque rara vez recurre a él. No se le asignan valores distintos de los que use la mesa.','[{"id": "bola-de-fuego", "nombre": "Bola de Fuego", "descripcion": "Hechizo ígneo que conoce de forma independiente a Limitless. Conjura una esfera de fuego como parte de su repertorio general. Puede detonarla cerca de sí mismo sin sufrir daño propio gracias a su protección innata. Ataque elemental habitual en el repertorio aprendido, aunque rara vez recurre a él. No se le asignan valores distintos de los que use la mesa.", "efecto": "dano", "estado": "Bola de Fuego", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Propia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-fire-nova", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('ed2c9c64-1443-5e82-88a2-b73d861b54fe','Recíproco Absoluto','habilidades_generales','habilidad','aprobado','Puede dirigir la reacción de un ataque hacia su fuente sin esperar a que exista contacto físico. Un hechizo lanzado desde lejos provoca una repercusión de fuerza en su emisor mientras todavía se desplaza. Kion designa el origen de la interacción. Contraataque remoto; castiga ataques físicos o mágicos sin tocar al lanzador. Requiere Limitless despierta. El efecto concreto sobre diferentes tipos de daño queda sujeto a las reglas del GM.','[{"id": "reciproco-absoluto", "nombre": "Recíproco Absoluto", "descripcion": "Puede dirigir la reacción de un ataque hacia su fuente sin esperar a que exista contacto físico. Un hechizo lanzado desde lejos provoca una repercusión de fuerza en su emisor mientras todavía se desplaza. Kion designa el origen de la interacción. Contraataque remoto; castiga ataques físicos o mágicos sin tocar al lanzador. Requiere Limitless despierta. El efecto concreto sobre diferentes tipos de daño queda sujeto a las reglas del GM.", "efecto": "estado", "estado": "Recíproco Absoluto", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Acción y Reacción", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-shockwave-ring", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('46744a09-aa81-5679-9835-edc2f9d674f0','Reacción Designada','habilidades_generales','habilidad','aprobado','Decide qué objeto o enemigo recibe la reacción de una fuerza, incluso si está distante. Kion golpea el aire y hace que la reacción se manifieste en un objetivo separado, o asigna a una estructura lejana la respuesta a una acción local. Ataque remoto y manipulación de interacciones sin proyectiles. La fuerza transmitida debe corresponder a una interacción sostenida por Limitless; no es un hechizo de creación ilimitada de energía.','[{"id": "reaccion-designada", "nombre": "Reacción Designada", "descripcion": "Decide qué objeto o enemigo recibe la reacción de una fuerza, incluso si está distante. Kion golpea el aire y hace que la reacción se manifieste en un objetivo separado, o asigna a una estructura lejana la respuesta a una acción local. Ataque remoto y manipulación de interacciones sin proyectiles. La fuerza transmitida debe corresponder a una interacción sostenida por Limitless; no es un hechizo de creación ilimitada de energía.", "efecto": "estado", "estado": "Reacción Designada", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Acción y Reacción", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-shockwave-ring", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('084a0eaf-98d7-5478-a083-4210077683c8','Reciprocidad Forzada','habilidades_generales','habilidad','aprobado','Vincula dos cuerpos separados para que una acción produzca su reacción sobre el segundo. El vínculo de Limitless sustituye la continuidad física necesaria en estado sellado. Kion puede mantener la condición mientras dure la técnica. Control de combate, castigo de movimientos y conexión entre objetivos sin contacto. No es extracción energética ni una cadena física convencional; el alcance y duración no están cuantificados.','[{"id": "reciprocidad-forzada", "nombre": "Reciprocidad Forzada", "descripcion": "Vincula dos cuerpos separados para que una acción produzca su reacción sobre el segundo. El vínculo de Limitless sustituye la continuidad física necesaria en estado sellado. Kion puede mantener la condición mientras dure la técnica. Control de combate, castigo de movimientos y conexión entre objetivos sin contacto. No es extracción energética ni una cadena física convencional; el alcance y duración no están cuantificados.", "efecto": "estado", "estado": "Reciprocidad Forzada", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Acción y Reacción", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-shockwave-ring", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('7815e42c-2c7f-5ec2-8f72-724779e67e07','Singularidad','habilidades_generales','habilidad','aprobado','Kion genera un auténtico agujero negro controlando gravedad y espacio-tiempo. La esfera contiene una singularidad que puede expandir o mantener confinada mediante Limitless. Absorción gravitatoria y destrucción extrema. Escala y persistencia dependen de las condiciones que formule.','[{"id": "singularidad", "nombre": "Singularidad", "descripcion": "Kion genera un auténtico agujero negro controlando gravedad y espacio-tiempo. La esfera contiene una singularidad que puede expandir o mantener confinada mediante Limitless. Absorción gravitatoria y destrucción extrema. Escala y persistencia dependen de las condiciones que formule.", "efecto": "estado", "estado": "Singularidad", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('eb17bcdd-6259-5f74-b7c2-b52b8850639e','Umbral Espacial','habilidades_generales','habilidad','aprobado','Abre portales conectados entre posiciones espaciales. La esfera actúa como boca de un portal; puede establecer parejas y recolocarlas. Traslado, intercepción o desvío de ataques, aperturas entre regiones. Es un uso ordinario de Axioma una vez despierto, no Paradoja.','[{"id": "umbral-espacial", "nombre": "Umbral Espacial", "descripcion": "Abre portales conectados entre posiciones espaciales. La esfera actúa como boca de un portal; puede establecer parejas y recolocarlas. Traslado, intercepción o desvío de ataques, aperturas entre regiones. Es un uso ordinario de Axioma una vez despierto, no Paradoja.", "efecto": "estado", "estado": "Umbral Espacial", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('970370a3-a1ff-559c-a6d3-09f62c7be1e4','Cronosfera','habilidades_generales','habilidad','aprobado','Crea una zona donde el tiempo transcurre de forma distinta. Kion establece condiciones temporales locales, desde ralentización hasta pausa. Alterar el ritmo de eventos dentro de un área definida. No es Bucle: modifica el tiempo, no impone percepción interminable.','[{"id": "cronosfera", "nombre": "Cronosfera", "descripcion": "Crea una zona donde el tiempo transcurre de forma distinta. Kion establece condiciones temporales locales, desde ralentización hasta pausa. Alterar el ritmo de eventos dentro de un área definida. No es Bucle: modifica el tiempo, no impone percepción interminable.", "efecto": "estado", "estado": "Cronosfera", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Inercia", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('2b6737ca-aa37-53d9-b432-b011d745fbef','Talión: Juicio Absoluto','habilidades_generales','habilidad','aprobado','Conecta dos puntos u objetivos y distribuye reacciones devastadoras entre ellos. Ya no depende de que dos cuerpos se toquen. Kion crea una esfera que designa las fuentes y receptores de fuerzas recíprocas; puede comprimir a un objetivo con fuerzas opuestas. Aplastar o neutralizar por conexión de reacciones, con control de condiciones en tiempo real. Limitless facilita la formulación, pero no lo convierte en una Paradoja ni obliga a Kion a ignorar toda consecuencia.','[{"id": "talion-juicio-absoluto", "nombre": "Talión: Juicio Absoluto", "descripcion": "Conecta dos puntos u objetivos y distribuye reacciones devastadoras entre ellos. Ya no depende de que dos cuerpos se toquen. Kion crea una esfera que designa las fuentes y receptores de fuerzas recíprocas; puede comprimir a un objetivo con fuerzas opuestas. Aplastar o neutralizar por conexión de reacciones, con control de condiciones en tiempo real. Limitless facilita la formulación, pero no lo convierte en una Paradoja ni obliga a Kion a ignorar toda consecuencia.", "efecto": "dano", "estado": "Talión: Juicio Absoluto", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Acción y Reacción", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-shockwave-ring", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('6d5e5c9d-a703-5711-b13e-c95222480165','Juicio de la Tierra: Cataclismo','habilidades_generales','habilidad','aprobado','Transforma una zona extensa en una red de reacciones, incluso entre masas separadas. Kion define pares de cuerpos o regiones cuyas fuerzas reaccionan entre sí. Puede hacer que montañas o secciones del terreno sufran tensiones y fracturas a enorme escala. Cataclismo geográfico controlado mediante una zona persistente. Sus límites concretos de escala, duración y daño permanecen abiertos al GM.','[{"id": "cataclismo", "nombre": "Juicio de la Tierra: Cataclismo", "descripcion": "Transforma una zona extensa en una red de reacciones, incluso entre masas separadas. Kion define pares de cuerpos o regiones cuyas fuerzas reaccionan entre sí. Puede hacer que montañas o secciones del terreno sufran tensiones y fracturas a enorme escala. Cataclismo geográfico controlado mediante una zona persistente. Sus límites concretos de escala, duración y daño permanecen abiertos al GM.", "efecto": "dano", "estado": "Juicio de la Tierra: Cataclismo", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Acción y Reacción", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-shockwave-ring", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('ca48669e-a56d-5a44-9f2a-78341bf0f3d5','Repercusión: Dominó','habilidades_generales','habilidad','aprobado','Una esfera genera múltiples Axiomas enlazados que repercuten sobre blancos distantes. Cada núcleo puede enviar la reacción de una colisión a otro, creando una cadena de golpes sin depender de continuidad física entre enemigos. Secuencia de impactos dirigida por Kion en varios puntos del escenario. La reacción interconectada la sostiene Limitless; no es una generación gratuita e ilimitada de energía.','[{"id": "domino", "nombre": "Repercusión: Dominó", "descripcion": "Una esfera genera múltiples Axiomas enlazados que repercuten sobre blancos distantes. Cada núcleo puede enviar la reacción de una colisión a otro, creando una cadena de golpes sin depender de continuidad física entre enemigos. Secuencia de impactos dirigida por Kion en varios puntos del escenario. La reacción interconectada la sostiene Limitless; no es una generación gratuita e ilimitada de energía.", "efecto": "dano", "estado": "Repercusión: Dominó", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Acción y Reacción", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-shockwave-ring", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('578046ed-096d-5b7a-8987-b78e10c37081','Extinción','habilidades_generales','habilidad','aprobado','Extrae la energía del núcleo vital hasta provocar una muerte casi instantánea. Drena a distancia la energía necesaria para mantener con vida un núcleo de YUGEN. Ataque letal a un objetivo alcanzado. No significa que desaparezca energía: se transfiere. Las defensas y contramedidas de enemigos quedan por definir.','[{"id": "extincion", "nombre": "Extinción", "descripcion": "Extrae la energía del núcleo vital hasta provocar una muerte casi instantánea. Drena a distancia la energía necesaria para mantener con vida un núcleo de YUGEN. Ataque letal a un objetivo alcanzado. No significa que desaparezca energía: se transfiere. Las defensas y contramedidas de enemigos quedan por definir.", "efecto": "estado", "estado": "Extinción", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Conservación", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-magic-circle", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('1c37df9d-00e5-50d1-87a9-cee5e443f037','Transmutación Energética','habilidades_generales','habilidad','aprobado','Transforma las manifestaciones de energía en una zona, incluso magia enemiga. Puede convertir una bola de fuego en lluvia al redistribuir calor y usar humedad o materia disponibles. Desarmar ofensivas y reescribir cómo se manifiestan. No es creación arbitraria de materia desde la nada.','[{"id": "transmutacion-energetica", "nombre": "Transmutación Energética", "descripcion": "Transforma las manifestaciones de energía en una zona, incluso magia enemiga. Puede convertir una bola de fuego en lluvia al redistribuir calor y usar humedad o materia disponibles. Desarmar ofensivas y reescribir cómo se manifiestan. No es creación arbitraria de materia desde la nada.", "efecto": "estado", "estado": "Transmutación Energética", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Conservación", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-magic-circle", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('6a5690c0-46c0-5a24-a08b-06fe6364bc9d','Silencio del Núcleo','habilidades_generales','habilidad','aprobado','Impide transferir energía del núcleo hacia técnicas mágicas. Interviene en el flujo energético que alimenta hechizos. Bloqueo de lanzamiento de magia dentro del área. A diferencia de Extinción, no mata de manera directa.','[{"id": "silencio-nucleo", "nombre": "Silencio del Núcleo", "descripcion": "Impide transferir energía del núcleo hacia técnicas mágicas. Interviene en el flujo energético que alimenta hechizos. Bloqueo de lanzamiento de magia dentro del área. A diferencia de Extinción, no mata de manera directa.", "efecto": "estado", "estado": "Silencio del Núcleo", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Conservación", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-magic-circle", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('faa492bf-b29d-5579-a941-27a02baa4a46','Colisión de Horizontes','habilidades_generales','habilidad','aprobado','Dos regiones espaciales son forzadas a responder entre sí mediante curvatura y fuerzas recíprocas. Kion curva el espacio y conecta puntos mediante fuerzas opuestas, comprimiendo las regiones como si el espacio chocara contra sí mismo. Destrucción espacial y compresión catastrófica. Requiere Limitless despierta. Es un Axioma de Fusión estabilizado, no una Paradoja.','[{"id": "colision-horizontes", "nombre": "Colisión de Horizontes", "descripcion": "Dos regiones espaciales son forzadas a responder entre sí mediante curvatura y fuerzas recíprocas. Kion curva el espacio y conecta puntos mediante fuerzas opuestas, comprimiendo las regiones como si el espacio chocara contra sí mismo. Destrucción espacial y compresión catastrófica. Requiere Limitless despierta. Es un Axioma de Fusión estabilizado, no una Paradoja.", "efecto": "dano", "estado": "Colisión de Horizontes", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Fusión", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('9de36aaa-705a-571d-afaa-69e34e74a455','Singularidad Eterna','habilidades_generales','habilidad','aprobado','Una singularidad gravitacional se alimenta de energía ambiental para sostener su crecimiento. Inercia configura la gravedad y Conservación aporta energía aprovechada del mundo. Kion puede mantener el fenómeno bajo las condiciones que establece. Ataque gravitacional persistente a escala devastadora. No crea energía gratuita: usa la disponible en el entorno. La estabilidad la aporta Limitless despierta.','[{"id": "singularidad-eterna", "nombre": "Singularidad Eterna", "descripcion": "Una singularidad gravitacional se alimenta de energía ambiental para sostener su crecimiento. Inercia configura la gravedad y Conservación aporta energía aprovechada del mundo. Kion puede mantener el fenómeno bajo las condiciones que establece. Ataque gravitacional persistente a escala devastadora. No crea energía gratuita: usa la disponible en el entorno. La estabilidad la aporta Limitless despierta.", "efecto": "estado", "estado": "Singularidad Eterna", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Fusión", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('e37a244e-62c5-5e30-9bc9-61d426321544','Retribución Universal','habilidades_generales','habilidad','aprobado','El gasto energético de ataques enemigos desencadena reacciones contra sus propios núcleos. Conservación interviene sobre la energía con la que se alimenta una técnica, mientras Acción y Reacción designa una repercusión de fuerza hacia su fuente. Zona donde intentar lanzar magia puede volverse letal para quien la activa. No equivale a Extinción: no vacía automáticamente todos los núcleos, sino que castiga la activación y el gasto de energía.','[{"id": "retribucion-universal", "nombre": "Retribución Universal", "descripcion": "El gasto energético de ataques enemigos desencadena reacciones contra sus propios núcleos. Conservación interviene sobre la energía con la que se alimenta una técnica, mientras Acción y Reacción designa una repercusión de fuerza hacia su fuente. Zona donde intentar lanzar magia puede volverse letal para quien la activa. No equivale a Extinción: no vacía automáticamente todos los núcleos, sino que castiga la activación y el gasto de energía.", "efecto": "estado", "estado": "Retribución Universal", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 1, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Fusión", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-wind-gust", "escala": 3}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('3e2c3896-d832-5b06-8d63-35eabaefa087','Exclusión','habilidades_generales','habilidad','aprobado','Kion hace que la realidad considere al objetivo un error y lo elimine. Un Axioma blanco y negro, caótico y casi autodestructivo, avanza intentando borrarse a sí mismo. La realidad corrige la contradicción eliminando lo afectado. Borrado existencial, no destrucción convencional. Exclusiva de Limitless despierta; es caótica e incontrolable.','[{"id": "exclusion", "nombre": "Exclusión", "descripcion": "Kion hace que la realidad considere al objetivo un error y lo elimine. Un Axioma blanco y negro, caótico y casi autodestructivo, avanza intentando borrarse a sí mismo. La realidad corrige la contradicción eliminando lo afectado. Borrado existencial, no destrucción convencional. Exclusiva de Limitless despierta; es caótica e incontrolable.", "efecto": "estado", "estado": "Exclusión", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Paradoja", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-void-implosion", "escala": 3, "pantalla": true}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('c0786ceb-b6e9-5223-ba0e-743e34968542','Bucle','habilidades_generales','habilidad','aprobado','Impone al objetivo los Ojos de la Verdad y lo atrapa en una percepción infinita. Usa los Ojos de la Verdad y sus DOS habilidades activas todavía por definir para forzar un ciclo interminable de información y procesamiento. Prisión mental comparable a un genjutsu infinito, pero basada en percepción real impuesta. Requiere definir las dos técnicas activas de los ojos.','[{"id": "bucle", "nombre": "Bucle", "descripcion": "Impone al objetivo los Ojos de la Verdad y lo atrapa en una percepción infinita. Usa los Ojos de la Verdad y sus DOS habilidades activas todavía por definir para forzar un ciclo interminable de información y procesamiento. Prisión mental comparable a un genjutsu infinito, pero basada en percepción real impuesta. Requiere definir las dos técnicas activas de los ojos.", "efecto": "estado", "estado": "Bucle", "cantidad": 1, "caras": 6, "modificador": 0, "coste_ph": 4, "coste_fatiga": 0, "duracion": 1, "tipo_dano": "Paradoja", "naturaleza": "magica", "elemento": "ninguno", "vfx": {"impacto": "foundry-void-implosion", "escala": 3, "pantalla": true}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,configuracion_dados,stats,slot_tipo) values ('84e3c816-1761-5ee6-9fb1-47b7a2ac2a36','Despertar Limitless','habilidades_generales','habilidad','aprobado','El ojo cósmico despierta. Espacio, tiempo y gravedad amplían sus leyes y habilitan Exclusión y Bucle.','[{"id": "despertar-limitless", "nombre": "Despertar Limitless", "efecto": "transformacion", "cantidad": 0, "caras": 6, "modificador": 0, "coste_ph": 0, "coste_fatiga": 0, "duracion": 0, "estado": "", "tipo_dano": "", "transformacion": {"id": "limitless", "nombre": "Limitless", "tipo": "poder", "etapas": [{"id": "despierto", "nombre": "Limitless despierto", "imagen_url": "/kion/despierto.webp", "stats": {"limitless_despierto": 1}, "habilidades": ["reciproco-absoluto", "reaccion-designada", "reciprocidad-forzada", "singularidad", "umbral-espacial", "cronosfera", "talion-juicio-absoluto", "cataclismo", "domino", "extincion", "transmutacion-energetica", "silencio-nucleo", "colision-horizontes", "singularidad-eterna", "retribucion-universal", "exclusion", "bucle"], "vfx": {"entrada": "espacial-morado-impacto"}}]}}]','{}','ninguno') on conflict (id) do nothing;
insert into public.forja_maestra(id,nombre,tipo,tipo_creacion,estado,descripcion,historia,imagen_url,formas_historia,stats,habilidades) values ('aa386a13-fec2-59b5-bd77-1fa6424fec28','Kion Vaelthorne','personajes','personaje','aprobado','Real · Mago errante acompañado por Navy.','Nombre de aventurero: Real. Registrado en el gremio como mago errante. Curioso, libre, lleno de energía; sarcástico y con tendencias sádicas. No es necesariamente malvado, pero tampoco un ejemplo de bondad.
